-- Check-in: modelo global versionado e uma atualização por pasta.
create table atualizacao_modelo (
 id uuid primary key, versao integer not null unique,
 conteudo jsonb not null, criado_em timestamptz not null default now()
);
create table atualizacao (
 id uuid primary key, consultoria_id uuid not null references consultoria(id),
 aluno_id uuid not null references aluno(id), pasta_id uuid not null unique references pasta_plano(id),
 data_atualizacao date not null, modelo_versao integer not null references atualizacao_modelo(versao),
 estado varchar(20) not null check (estado in ('ABERTA','ENVIADA','REVISADA')),
 respostas jsonb not null default '{}', enviada_em timestamptz,
 atraso_ate date, atraso_motivo varchar(300), atraso_avisado_em timestamptz,
 feedback text, feedback_em timestamptz, feedback_editado_em timestamptz,
 feedback_por uuid references usuario(id), feedback_visto_em timestamptz,
 versao bigint not null default 0, criado_em timestamptz not null default now()
);
create index ix_atualizacao_painel on atualizacao(consultoria_id,estado,data_atualizacao);
insert into atualizacao_modelo(id,versao,conteudo) values ('b582a268-f6e7-44fc-9b97-cf379f485c26',1,'{"versao": 1, "instrucoes": ["O feedback deve ser enviado no dia da atualização. Caso ocorram atrasos, avise previamente.", "Atualização de peso e fotos em jejum"], "secoes": [{"titulo": "Atualização", "perguntas": [{"id": "data", "tipo": "DATA_AUTOMATICA", "rotulo": "Atualização", "obrigatoria": false}, {"id": "peso", "tipo": "PESO", "rotulo": "Peso (em jejum)", "obrigatoria": true}, {"id": "fotos", "tipo": "FOTOS", "rotulo": "Fotos em jejum", "obrigatoria": false}, {"id": "psicologico", "tipo": "TEXTO_LONGO", "rotulo": "Como foi o seu psicológico durante o mês?", "obrigatoria": false}, {"id": "sono", "tipo": "NOTA", "rotulo": "De 0 a 10, como foi o seu sono?", "obrigatoria": true}, {"id": "estresse", "tipo": "TEXTO_LONGO", "rotulo": "Passou algum momento de estresse?", "obrigatoria": false}]}, {"titulo": "✅ Alimentar", "perguntas": [{"id": "alim_desempenho", "tipo": "NOTA", "rotulo": "Desempenho (0 a 10)", "obrigatoria": true}, {"id": "alim_faltou", "tipo": "TEXTO_LONGO", "rotulo": "Sentiu que faltou algo durante a dieta?", "obrigatoria": false}, {"id": "alim_livre", "tipo": "TEXTO_LONGO", "rotulo": "O que comeu em cada refeição livre e em qual quantidade?", "obrigatoria": false}, {"id": "alim_digestao", "tipo": "TEXTO", "rotulo": "Como está sua digestão?", "obrigatoria": false}, {"id": "alim_fome", "tipo": "TEXTO", "rotulo": "Momento que mais ficou com fome", "obrigatoria": false}, {"id": "alim_enjoou", "tipo": "TEXTO_LONGO", "rotulo": "Algum alimento que enjoou ou gostaria de substituir?", "obrigatoria": false}, {"id": "alim_incluir", "tipo": "TEXTO_LONGO", "rotulo": "Gostaria de comer algo durante as refeições (e em qual refeição)?", "obrigatoria": false}]}, {"titulo": "✅ Treino", "perguntas": [{"id": "treino_dias", "tipo": "TEXTO", "rotulo": "Quantos dias por semana está conseguindo treinar?", "obrigatoria": false}, {"id": "treino_desempenho", "tipo": "NOTA", "rotulo": "Desempenho (0 a 10)", "obrigatoria": true}, {"id": "treino_dores", "tipo": "TEXTO_LONGO", "rotulo": "Sentiu dores ou dificuldades? Quais as dores? Em quais exercícios?", "obrigatoria": false}, {"id": "treino_descanso", "tipo": "TEXTO", "rotulo": "Precisou fazer descanso no meio da semana? Se sim, qual dia?", "obrigatoria": false}, {"id": "treino_acrescentar", "tipo": "TEXTO_LONGO", "rotulo": "Algo a acrescentar?", "obrigatoria": false}]}, {"titulo": "Feedbacks dos treinos durante esse período", "perguntas": [{"id": "fb_recuperacao", "tipo": "TEXTO_LONGO", "rotulo": "De 0 a 10, como foi a recuperação de cada dia?", "obrigatoria": false}, {"id": "fb_dores", "tipo": "TEXTO_LONGO", "rotulo": "Sentiu dores durante a semana?", "obrigatoria": false}, {"id": "fb_fadiga", "tipo": "TEXTO_LONGO", "rotulo": "Sentiu muita fadiga durante a semana?", "obrigatoria": false}, {"id": "fb_desgastante", "tipo": "TEXTO", "rotulo": "Qual dia foi mais desgastante?", "obrigatoria": false}, {"id": "fb_substituiu", "tipo": "TEXTO_LONGO", "rotulo": "Teve algum exercício que substituiu por não ter o maquinário próprio na sua academia? Se sim, quais?", "obrigatoria": false}, {"id": "fb_recuperou", "tipo": "TEXTO_LONGO", "rotulo": "Seu músculo recuperou até a próxima sessão de treino? (ajuda: \"Exemplo: treinei perna na segunda e na outra sessão de pernas treinei com dores\")", "obrigatoria": false}, {"id": "fb_pos_treino", "tipo": "NOTAS_POR_DIA", "rotulo": "De 0 a 10, como você se sentiu pós-treino nos dias abaixo", "obrigatoria": false, "dias": [1, 2, 3, 4, 5, 6]}, {"id": "fb_mes", "tipo": "TEXTO_LONGO", "rotulo": "Me diz brevemente um feedback desse mês ou alguma observação relevante para o seu desenvolvimento", "obrigatoria": false}]}]}');
